@OptIn(ExperimentalMaterial3Api::class) @Composable private fun ExpenseEditor(existing:JsonObject,options:JsonObject,saving:Boolean,onClose:()->Unit,onSave:(JsonObject)->Unit,onRecurring:(JsonObject)->Unit){var branch by remember{mutableStateOf(existing.str("branchId"))};var category by remember{mutableStateOf(existing.str("categoryId"))};var account by remember{mutableStateOf(existing.str("moneyAccountId"))};var project by remember{mutableStateOf(existing.str("projectId"))};var type by remember{mutableStateOf(existing.str("type").ifBlank{"OFFICE_EXPENSE"})};var amount by remember{mutableStateOf(existing.str("taxableAmount"))};var tax by remember{mutableStateOf(existing.str("taxRate").ifBlank{"0"})};var date by remember{mutableStateOf(existing.str("transactionDate").take(10).ifBlank{java.time.LocalDate.now().toString()})};var reference by remember{mutableStateOf(existing.str("reference"))};var notes by remember{mutableStateOf(existing.str("notes"))};var recurring by remember{mutableStateOf(false)};AlertDialog(onDismissRequest=onClose,title={Text(if(existing.containsKey("id"))"Edit draft expense" else "New expense")},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{Select("Branch",branch,options.array("branches"),{branch=it})};item{Select("Category",category,options.array("categories"),{category=it})};item{Select("Payment account",account,options.array("moneyAccounts"),{account=it})};item{Select("Project (optional)",project,options.array("projects"),{project=it})};item{SelectText("Type",type,listOf("OFFICE_EXPENSE","PROJECT_EXPENSE","REIMBURSEMENT","OTHER_INCOME")){type=it}};item{OutlinedTextField(amount,{amount=it},label={Text("Taxable amount")})};item{OutlinedTextField(tax,{tax=it},label={Text("GST / tax rate")})};item{OutlinedTextField(date,{date=it},label={Text("Expense date (YYYY-MM-DD)")})};item{OutlinedTextField(reference,{reference=it},label={Text("Reference")})};item{OutlinedTextField(notes,{notes=it},label={Text("Notes")})};item{Row{Checkbox(recurring,{recurring=it});Text("Create recurring monthly schedule",Modifier.padding(top=12.dp))}}}},confirmButton={Button(enabled=!saving&&branch.isNotBlank()&&category.isNotBlank()&&amount.isNotBlank(),onClick={val p=buildJsonObject{put("branchId",branch);project.takeIf{it.isNotBlank()}?.let{put("projectId",it)};put("categoryId",category);put("type",type);put("transactionDate",date);put("taxableAmount",amount);put("taxRate",tax);put("cessRate","0");put("taxMode","EXCLUSIVE");put("taxCreditTreatment","ELIGIBLE");account.takeIf{it.isNotBlank()}?.let{put("moneyAccountId",it)};reference.takeIf{it.isNotBlank()}?.let{put("reference",it)};notes.takeIf{it.isNotBlank()}?.let{put("notes",it)}};onSave(p);if(recurring)onRecurring(buildJsonObject{put("branchId",branch);project.takeIf{it.isNotBlank()}?.let{put("projectId",it)};put("categoryId",category);put("frequency","MONTHLY");put("nextDueDate",date);put("amount",amount)})}){Text("Save")}},dismissButton={TextButton(onClose){Text("Cancel")}})}
